/* Lunar Landing Site Navigator: one screen. Earth and the Moon in 3D at true scale, and a landing check for any site
   and time (sunlight, line of sight to Earth, flat ground). Everything else lives in the About sheet. */
import React, { useEffect, useRef, useState } from "react";
import { EarthMoon } from "./EarthMoon";
import { About } from "./About";

export class ErrorBoundary extends React.Component<{ children: React.ReactNode }, { err: boolean }> {
  state = { err: false };
  static getDerivedStateFromError() {
    return { err: true };
  }
  render() {
    if (!this.state.err) return this.props.children;
    return (
      <div className="crash">
        <h1>Something went wrong</h1>
        <p>Reload the page to try again.</p>
        <button className="btn" onClick={() => location.reload()}>
          Reload
        </button>
      </div>
    );
  }
}

/** A still field of faint stars behind the scene. */
function Stars() {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const cv = ref.current!;
    const ctx = cv.getContext("2d");
    if (!ctx) return;
    let seed = 7;
    const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    const stars = Array.from({ length: 260 }, () => ({ x: rnd(), y: rnd(), r: rnd() * 1.1 + 0.2, a: 0.2 + rnd() * 0.5 }));
    const draw = () => {
      const w = (cv.width = window.innerWidth), h = (cv.height = window.innerHeight);
      ctx.clearRect(0, 0, w, h);
      for (const s of stars) {
        ctx.fillStyle = `rgba(235,235,240,${s.a})`;
        ctx.beginPath();
        ctx.arc(s.x * w, s.y * h, s.r, 0, 7);
        ctx.fill();
      }
    };
    draw();
    window.addEventListener("resize", draw);
    return () => window.removeEventListener("resize", draw);
  }, []);
  return <canvas ref={ref} className="stars" aria-hidden="true" />;
}

export default function App() {
  const [about, setAbout] = useState(false);
  return (
    <div className="app">
      <Stars />
      <header className="top">
        <div className="brand">
          <div className="brand-mark" aria-hidden="true" />
          <div>
            <h1>Lunar Landing Site Navigator</h1>
            <p>Can a lander work here? Sunlight, Earth and slope, at true scale</p>
          </div>
        </div>
        <button className="btn" onClick={() => setAbout(true)}>
          About and judging
        </button>
      </header>
      <EarthMoon onAbout={() => setAbout(true)} />
      {about && <About onClose={() => setAbout(false)} />}
    </div>
  );
}
